t.script:
//
                document.addEventListener('DOMContentLoaded', function() {
                    const steps = [
                        document.getElementById('step1'),
                        document.getElementById('step2'),
                        document.getElementById('step3')
                    ];
                    const indicators = [
                        document.getElementById('ind-step1'),
                        document.getElementById('ind-step2'),
                        document.getElementById('ind-step3')
                    ];
                    const progress = document.getElementById('wizard-progress');
                    const errorBox = document.getElementById('error-message');

                    function updateUI(stepIndex) {
                        // Ocultar todos
                        steps.forEach(s => s.classList.add('d-none'));
                        // Mostrar actual
                        steps[stepIndex - 1].classList.remove('d-none');

                        // Actualizar indicadores
                        indicators.forEach((ind, i) => {
                            if(i < stepIndex) {
                                ind.classList.replace('bg-light', 'bg-primary');
                                ind.classList.replace('text-muted', 'text-white');
                                ind.classList.remove('border');
                            } else {
                                ind.classList.replace('bg-primary', 'bg-light');
                                ind.classList.replace('text-white', 'text-muted');
                                ind.classList.add('border');
                            }
                        });

                        // Barra de progreso (0%, 50%, 100%)
                        progress.style.width = ((stepIndex - 1) * 50) + '%';
                        errorBox.classList.add('d-none');
                    }

                    function validateStep(stepIndex) {
                        let isValid = true;
                        const fields = document.querySelectorAll('.required-step' + stepIndex);
                        fields.forEach(f => {
                            if(!f.value.trim()) {
                                isValid = false;
                                f.classList.add('is-invalid');
                            } else {
                                f.classList.remove('is-invalid');
                            }
                        });
                        return isValid;
                    }

                    // Botones Siguiente
                    document.querySelectorAll('.btn-next').forEach(btn => {
                        btn.addEventListener('click', function() {
                            let currentStep = parseInt(this.getAttribute('data-step'));
                            if(validateStep(currentStep)) {
                                updateUI(currentStep + 1);
                            } else {
                                errorBox.textContent = 'Por favor, completa todos los campos requeridos marcados en rojo.';
                                errorBox.classList.remove('d-none');
                            }
                        });
                    });

                    // Botones Atrás
                    document.querySelectorAll('.btn-prev').forEach(btn => {
                        btn.addEventListener('click', function() {
                            let currentStep = parseInt(this.getAttribute('data-step'));
                            updateUI(currentStep - 1);
                        });
                    });

                    // Enviar form y Validar AJAX
                    const btnSubmit = document.getElementById('btn-submit-wizard');
                    btnSubmit.addEventListener('click', async function() {
                        if(!validateStep(3)) {
                            errorBox.textContent = 'Por favor, selecciona una fecha y hora.';
                            errorBox.classList.remove('d-none');
                            return;
                        }

                        btnSubmit.disabled = true;
                        btnSubmit.innerHTML = '<i class="fa fa-spinner fa-spin me-2"></i> Verificando...';

                        const dateVal = document.getElementById('date').value;

                        try {
                            const response = await fetch('/taller/cita/check_availability', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/json',
                                },
                                body: JSON.stringify({
                                    jsonrpc: "2.0",
                                    method: "call",
                                    params: { date: dateVal }
                                })
                            });

                            const data = await response.json();
                            const result = data.result;

                            if (result && result.available) {
                                document.getElementById('cita-wizard-form').submit();
                            } else {
                                errorBox.textContent = result ? result.message : 'Error al verificar disponibilidad.';
                                errorBox.classList.remove('d-none');
                                btnSubmit.disabled = false;
                                btnSubmit.innerHTML = '<i class="fa fa-check-circle me-2"></i> SOLICITAR CITA';
                            }
                        } catch (err) {
                            console.error(err);
                            errorBox.textContent = 'Error de conexión. Intente nuevamente.';
                            errorBox.classList.remove('d-none');
                            btnSubmit.disabled = false;
                            btnSubmit.innerHTML = '<i class="fa fa-check-circle me-2"></i> SOLICITAR CITA';
                        }
                    });
                });
//
